import { describe, it, expect } from 'vitest';
import { validateSqlQuery } from './server/debug-helpers';

describe('validateSqlQuery', () => {
  it('allows SELECT', () => {
    expect(validateSqlQuery('SELECT * FROM flights')).toEqual({ valid: true });
  });

