        new Date(latestGuernseyTs) >= new Date(entry.statusTimestamp)
      ) return false;
      return true;
    });

    const data = {
      flight,
      statusHistory,
      weatherMap,
      daylightMap,
      position: positionRows[0] ?? null,
      rotationFlights,
      times,
    };

    return debugResponse([data], performance.now() - t0);
  } catch (err) {
    console.error('[debug/ui/flight]', err);
    return debugError('Query failed', 500);
  }
};

