import type { RequestHandler } from './$types';
import { db, flights, flightStatusHistory, weatherData, aircraftPositions, flightTimes, airportDaylight } from '$lib/server/db';
import { debugResponse, debugError } from '$lib/server/debug-helpers';
import { eq, desc, and, lte, gte, inArray, isNotNull, asc } from 'drizzle-orm';

/**
 * Mirrors the flight detail load function.
 * GET /api/debug/ui/flight/:id
 */
export const GET: RequestHandler = async ({ params }) => {
  const t0 = performance.now();
  try {
    const id = parseInt(params.id, 10);
    if (isNaN(id)) return debugError('Invalid flight ID', 400);

    const [flight] = await db.select().from(flights).where(eq(flights.id, id)).limit(1);
    if (!flight) return debugError('Flight not found', 404);

    const flightTime = flight.scheduledDeparture;
    const windowStart = new Date(flightTime.getTime() - 90 * 60000);
    const windowEnd   = new Date(Math.max(flightTime.getTime() + 90 * 60000, Date.now()));
    const airports    = [...new Set([flight.departureAirport, flight.arrivalAirport])];

    const depDate = flight.scheduledDeparture.toISOString().split('T')[0];
    const arrDate = flight.scheduledArrival.toISOString().split('T')[0];

    const rotationStart = new Date(flight.scheduledDeparture.getTime() - 24 * 60 * 60 * 1000);
    const rotationFlights = flight.aircraftRegistration
      ? await db.select({
          id: flights.id, flightNumber: flights.flightNumber,
          departureAirport: flights.departureAirport, arrivalAirport: flights.arrivalAirport,
          scheduledDeparture: flights.scheduledDeparture, scheduledArrival: flights.scheduledArrival,
          actualDeparture: flights.actualDeparture, actualArrival: flights.actualArrival,
          status: flights.status, canceled: flights.canceled, delayMinutes: flights.delayMinutes,
        })
        .from(flights)
        .where(and(
          eq(flights.aircraftRegistration, flight.aircraftRegistration),
          gte(flights.scheduledDeparture, rotationStart),
          isNotNull(flights.aircraftRegistration),
        ))
        .orderBy(asc(flights.scheduledDeparture))
      : [];

    const [rawStatusHistory, weatherRows, positionRows, times, daylightRows] = await Promise.all([
      db.select().from(flightStatusHistory)
        .where(eq(flightStatusHistory.flightId, id))
        .orderBy(desc(flightStatusHistory.statusTimestamp)),
      db.select().from(weatherData)
        .where(and(
          inArray(weatherData.airportCode, airports),
          gte(weatherData.timestamp, windowStart),
          lte(weatherData.timestamp, windowEnd),
        ))
        .orderBy(desc(weatherData.timestamp)),
      db.select().from(aircraftPositions)
        .where(eq(aircraftPositions.flightId, id))
        .orderBy(desc(aircraftPositions.positionTimestamp))
        .limit(1),
      db.select().from(flightTimes).where(eq(flightTimes.flightId, id)),
      db.select().from(airportDaylight)
        .where(and(
          inArray(airportDaylight.airportCode, airports),
          inArray(airportDaylight.date, [depDate, arrDate]),
        )),
    ]);

    // WeatherMap — most recent past record per airport
    const weatherMap: Record<string, typeof weatherData.$inferSelect> = {};
    const now = new Date();
    for (const row of weatherRows) {
      const existing = weatherMap[row.airportCode];
      const rowTs = new Date(row.timestamp).getTime();
      if (!existing) { weatherMap[row.airportCode] = row; continue; }
      const existingTs = new Date(existing.timestamp).getTime();
      if (rowTs <= now.getTime() && existingTs > now.getTime()) {
        weatherMap[row.airportCode] = row;
      } else if (rowTs <= now.getTime() && existingTs <= now.getTime() && rowTs > existingTs) {
        weatherMap[row.airportCode] = row;
      }
    }

    // Daylight map
    const daylightMap: Record<string, typeof airportDaylight.$inferSelect[]> = {};
    for (const row of daylightRows) {
      if (!daylightMap[row.airportCode]) daylightMap[row.airportCode] = [];
      daylightMap[row.airportCode].push(row);
    }

    // Deduplicate status history
    const latestGuernseyTs = rawStatusHistory
      .find(e => e.source === 'guernsey_airport')
      ?.statusTimestamp ?? null;
    const seenBySource = new Map<string, Set<string>>();
    const statusHistory = rawStatusHistory.filter((entry) => {
      const key = entry.source;
      if (!seenBySource.has(key)) seenBySource.set(key, new Set());
      const seen = seenBySource.get(key)!;
      if (seen.has(entry.statusMessage)) return false;
      seen.add(entry.statusMessage);
      if (
        entry.source === 'fr24' &&
        entry.statusMessage.toLowerCase().startsWith('estimated dep') &&
        latestGuernseyTs !== null &&
        new Date(latestGuernseyTs) >= new Date(entry.statusTimestamp)
      ) return false;
      return true;
    });

    const data = {
      flight,
      statusHistory,
      weatherMap,
      daylightMap,
      position: positionRows[0] ?? null,
      rotationFlights,
      times,
    };

    return debugResponse([data], performance.now() - t0);
  } catch (err) {
    console.error('[debug/ui/flight]', err);
    return debugError('Query failed', 500);
  }
};

/**
 * Typed Drizzle query functions for stats page
 * Replaces raw SQL with type-safe query builders
 */

import { db } from '$lib/server/db';
import { flights, historicalWeather } from '@airways/database/schema';
import {
  sql,
  desc,
  isNotNull,
} from 'drizzle-orm';
import type {
  FilterConfig,
  HeroStats,
  DelayDistribution,
  DayOfWeekStats,
  HourlyStats,
  DailyStats,
  RouteStats,
  FlightNumberStats,
  AircraftStats,
  DelayRecord,
  DailyOtpStats,
  MonthlyStats,
  WeatherBandStats,
  WeatherCodeStats,
  CrosswindStats,
  WorstWeatherDay,
  DelayImpact,
  WorstDelayDay,
  FilterOptions,
} from './types';

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Build airline filter SQL fragment
 */
function buildAirlineFilter(airline?: string): ReturnType<typeof sql> {
  if (airline) {
    return sql`(UPPER(SUBSTRING(${flights.flightNumber} FROM 1 FOR 2)) = ${airline})`;
  }
  return sql`(${flights.flightNumber} ILIKE 'GR%' OR ${flights.flightNumber} ILIKE 'BA%')`;
}

/**
 * Build date filter SQL fragment
 */
function buildDateFilter(range: FilterConfig['range']): ReturnType<typeof sql> {
  if (range.type === 'custom' && range.dateFrom && range.dateTo) {
    return sql`AND ${flights.flightDate} BETWEEN ${range.dateFrom} AND ${range.dateTo}`;
  }
  if (range.type === '30') {
    return sql`AND ${flights.flightDate} >= CURRENT_DATE - INTERVAL '30 days'`;
  }
  if (range.type === '90') {
    return sql`AND ${flights.flightDate} >= CURRENT_DATE - INTERVAL '90 days'`;
  }
  return sql``;
}

/**
 * Build route minimum filter SQL fragment (for regular routes)
 */
function buildRouteMinFilter(
  range: FilterConfig['range'],
  minFlightsPerRoute: number,
): ReturnType<typeof sql> {
  let routeMinDateFilter: ReturnType<typeof sql>;

  if (range.type === 'custom' && range.dateFrom && range.dateTo) {
    routeMinDateFilter = sql`AND f2.flight_date BETWEEN ${range.dateFrom} AND ${range.dateTo}`;
  } else if (range.type === '30') {
    routeMinDateFilter = sql`AND f2.flight_date >= CURRENT_DATE - INTERVAL '30 days'`;
  } else if (range.type === '90') {
    routeMinDateFilter = sql`AND f2.flight_date >= CURRENT_DATE - INTERVAL '90 days'`;
  } else {
    routeMinDateFilter = sql``;
  }

  return sql`AND (${flights.departureAirport}, ${flights.arrivalAirport}) IN (
    SELECT f2.departure_airport, f2.arrival_airport FROM flights f2
    WHERE (f2.flight_number ILIKE 'GR%' OR f2.flight_number ILIKE 'BA%')
      AND f2.departure_airport != f2.arrival_airport
      ${routeMinDateFilter}
    GROUP BY f2.departure_airport, f2.arrival_airport
    HAVING COUNT(*) >= ${minFlightsPerRoute}
  )`;
}

/**
 * Build route filter for specific routes
 */
function buildRouteFilter(
  routes: FilterConfig['routes'],
): ReturnType<typeof sql> {
  if (!routes || routes.length === 0) {
    return sql``;
  }

  const conditions = routes.map(
    (r) => sql`(${flights.departureAirport} = ${r.dep} AND ${flights.arrivalAirport} = ${r.arr})`,
  );
  return sql`AND (${sql.join(conditions, sql` OR `)})`;
}

/**
 * Build direction filter
 */
function buildDirectionFilter(direction?: string): ReturnType<typeof sql> {
  if (direction === 'dep') {
    return sql`AND ${flights.departureAirport} = 'GCI'`;
  }
  if (direction === 'arr') {
    return sql`AND ${flights.arrivalAirport} = 'GCI'`;
  }
  return sql``;
}

/**
 * Build day of week filter
 */
function buildDowFilter(dow?: number): ReturnType<typeof sql> {
  if (dow === undefined || dow === null || isNaN(dow) || dow < 0 || dow > 6) {
    return sql``;
  }
  return sql`AND EXTRACT(DOW FROM ${flights.flightDate}) = ${dow}`;
}

/**
 * Build period filter (season/month)
 */
function buildPeriodFilter(
  season?: string,
  month?: number,
): ReturnType<typeof sql> {
  if (month !== undefined && month !== null && !isNaN(month) && month >= 1 && month <= 12) {
    return sql`AND EXTRACT(MONTH FROM ${flights.flightDate}) = ${month}`;
  }

  switch (season) {
    case 'summer':
      return sql`AND EXTRACT(MONTH FROM ${flights.flightDate}) IN (6, 7, 8)`;
    case 'winter':
      return sql`AND EXTRACT(MONTH FROM ${flights.flightDate}) IN (12, 1, 2)`;
    case 'spring':
      return sql`AND EXTRACT(MONTH FROM ${flights.flightDate}) IN (3, 4, 5)`;
    case 'autumn':
      return sql`AND EXTRACT(MONTH FROM ${flights.flightDate}) IN (9, 10, 11)`;
    default:
      return sql``;
  }
}

/**
 * Build year filter
 */
function buildYearFilter(year?: number): ReturnType<typeof sql> {
  if (year === undefined || year === null || isNaN(year) || year < 2000 || year > 2100) {
    return sql``;
  }
  return sql`AND EXTRACT(YEAR FROM ${flights.flightDate}) = ${year}`;
}

/**
 * Build complete WHERE clause
 */
function buildWhereClause(filters: FilterConfig): ReturnType<typeof sql> {
  const airlineFilter = buildAirlineFilter(filters.airline);
  const dateFilter = buildDateFilter(filters.range);
  const routeMinFilter = buildRouteMinFilter(
    filters.range,
    filters.minFlightsPerRoute,
  );
  const routeFilter = buildRouteFilter(filters.routes);
  const directionFilter = buildDirectionFilter(filters.direction);
  const dowFilter = buildDowFilter(filters.dow);
  const periodFilter = buildPeriodFilter(filters.season, filters.month);
  const yearFilter = buildYearFilter(filters.year);

  return sql`${airlineFilter} ${dateFilter} ${routeMinFilter} ${routeFilter} ${directionFilter} ${dowFilter} ${periodFilter} ${yearFilter}`;
}

/**
 * Build route WHERE clause (without route-specific filter)
 */
function buildRoutesWhereClause(filters: FilterConfig): ReturnType<typeof sql> {
  const airlineFilter = buildAirlineFilter(filters.airline);
  const dateFilter = buildDateFilter(filters.range);
  const routeMinFilter = buildRouteMinFilter(
    filters.range,
    filters.minFlightsPerRoute,
  );
  const directionFilter = buildDirectionFilter(filters.direction);
  const dowFilter = buildDowFilter(filters.dow);
  const periodFilter = buildPeriodFilter(filters.season, filters.month);
  const yearFilter = buildYearFilter(filters.year);

  return sql`${airlineFilter} ${dateFilter} ${routeMinFilter} ${directionFilter} ${dowFilter} ${periodFilter} ${yearFilter}`;
}

/**
 * Build weather WHERE clause
 */
function buildWeatherWhereClause(filters: FilterConfig): ReturnType<typeof sql> {
  const airlineFilter = buildAirlineFilter(filters.airline);

  let dateFilter: ReturnType<typeof sql>;
  if (filters.range.type === 'custom' && filters.range.dateFrom && filters.range.dateTo) {
    dateFilter = sql`AND ${flights.flightDate} BETWEEN ${filters.range.dateFrom} AND ${filters.range.dateTo}`;
  } else if (filters.range.type === '30') {
    dateFilter = sql`AND ${flights.flightDate} >= CURRENT_DATE - INTERVAL '30 days'`;
  } else if (filters.range.type === '90') {
    dateFilter = sql`AND ${flights.flightDate} >= CURRENT_DATE - INTERVAL '90 days'`;
  } else {
    dateFilter = sql``;
  }

  const routeMinFilter = buildRouteMinFilter(
    filters.range,
    filters.minFlightsPerRoute,
  );
  const routeFilter = buildRouteFilter(filters.routes);
  const directionFilter = buildDirectionFilter(filters.direction);
  const dowFilter = buildDowFilter(filters.dow);
  const periodFilter = buildPeriodFilter(filters.season, filters.month);
  const yearFilter = buildYearFilter(filters.year);

  return sql`${airlineFilter} ${dateFilter} ${routeMinFilter} ${routeFilter} ${directionFilter} ${dowFilter} ${periodFilter} ${yearFilter}`;
}

